ALTER TABLE media ADD COLUMN content_hash text;
CREATE TABLE order_workflows(order_id uuid PRIMARY KEY REFERENCES orders(id),version integer NOT NULL DEFAULT 1,data jsonb NOT NULL);
CREATE TABLE after_sale_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),version integer NOT NULL DEFAULT 1,data jsonb NOT NULL);
CREATE TABLE commerce_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES orders(id),actor_id uuid REFERENCES users(id),request_id text NOT NULL UNIQUE,request_hash text NOT NULL,action text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commerce_jobs(key text PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),kind text NOT NULL,version integer NOT NULL,due_at timestamptz NOT NULL,done boolean NOT NULL DEFAULT false);
CREATE INDEX commerce_jobs_due ON commerce_jobs(due_at) WHERE NOT done;
CREATE TABLE seller_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seller_id uuid NOT NULL REFERENCES users(id),order_id uuid REFERENCES orders(id),reference text NOT NULL UNIQUE,kind text NOT NULL,available_delta integer NOT NULL DEFAULT 0,unsettled_delta integer NOT NULL DEFAULT 0,frozen_delta integer NOT NULL DEFAULT 0,reserved_delta integer NOT NULL DEFAULT 0,commission_delta integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX seller_ledger_owner ON seller_ledger(seller_id,created_at);
CREATE TABLE simulated_payout_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seller_id uuid NOT NULL REFERENCES users(id),label text NOT NULL,verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE simulated_withdrawals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seller_id uuid NOT NULL REFERENCES users(id),account_id uuid NOT NULL REFERENCES simulated_payout_accounts(id),account_label text NOT NULL,request_id text NOT NULL UNIQUE,amount_fen integer NOT NULL CHECK(amount_fen>0),status text NOT NULL CHECK(status IN ('pending','processing','succeeded','failed')),reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),buyer_id uuid NOT NULL REFERENCES users(id),seller_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(buyer_id,seller_id),CHECK(buyer_id<>seller_id));
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations(id),sender_id uuid NOT NULL REFERENCES users(id),request_id text NOT NULL,kind text NOT NULL CHECK(kind IN ('text','order','product')),body text NOT NULL,object_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(sender_id,request_id));
CREATE INDEX messages_conversation ON messages(conversation_id,created_at,id);
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),dedupe_key text NOT NULL UNIQUE,kind text NOT NULL,object_id uuid NOT NULL,summary text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_owner ON notifications(user_id,created_at);
CREATE TABLE support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),order_id uuid REFERENCES orders(id),request_id text NOT NULL UNIQUE,kind text NOT NULL CHECK(kind IN ('support','feedback')),category text NOT NULL,text text NOT NULL,status text NOT NULL DEFAULT 'submitted',replies jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE users ADD COLUMN is_supervisor boolean NOT NULL DEFAULT false;
INSERT INTO order_workflows(order_id,data) SELECT id,jsonb_build_object('stage','awaitingService','evidenceIds','[]'::jsonb,'acceptanceDue',null,'extended',false,'terminatedAt',null,'activeCaseId',null,'caseCount',0,'refundedFen',0,'settled',false,'holds','{}'::jsonb,'availableFen',0,'unsettledFen',total_fen,'frozenFen',0,'commissionFen',0,'startedAt',null,'completedAt',null) FROM orders WHERE paid_at IS NOT NULL;
INSERT INTO seller_ledger(seller_id,order_id,reference,kind,unsettled_delta) SELECT seller_id,id,'payment:'||id,'paymentHeld',total_fen FROM orders WHERE paid_at IS NOT NULL;
ALTER TABLE media DROP CONSTRAINT media_kind_check;
ALTER TABLE media ADD CONSTRAINT media_kind_check CHECK(kind IN ('avatar','voice','evidenceImage','evidenceVideo'));
CREATE TABLE evidence_redactions(original_id uuid PRIMARY KEY REFERENCES media(id),order_id uuid NOT NULL REFERENCES orders(id),redacted_id uuid NOT NULL REFERENCES media(id),reviewer_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
